import React, { useState, useEffect } from "react";
import axios from "axios";
import QuestionCard from "./component/QuestionCard";
import "./App.css";

function App() {
  const [availableQuestions, setAvailableQuestions] = useState([]);
  const [shouldMaskInput, setShouldMaskInput] = useState(false);

  const createEmptyForm = () => Array(5).fill(null).map(() => ({ 
    selectedQuestionText: "", 
    userAnswer: "", 
    confirmedAnswer: "" 
  }));

  const [securityFormEntries, setSecurityFormEntries] = useState(createEmptyForm());

  useEffect(() => {
    axios.get("http://localhost:3001/questions")
      .then((response) => setAvailableQuestions(response.data))
      .catch((error) => console.error("Data Fetch Error:", error));
  }, []);

  const updateFormEntry = (index, fieldName, newValue) => {
    const updatedEntries = [...securityFormEntries];
    updatedEntries[index][fieldName] = newValue;
    setSecurityFormEntries(updatedEntries);
  };

  const validateAndSubmitForm = async () => {
    const isFormComplete = securityFormEntries.every(entry => 
      entry.selectedQuestionText && entry.userAnswer && entry.confirmedAnswer
    );
    const areAnswersMatching = securityFormEntries.every(entry => 
      entry.userAnswer === entry.confirmedAnswer
    );

    if (!isFormComplete) return alert("Please complete all 5 security steps.");
    if (!areAnswersMatching) return alert("Validation failed: Answers do not match.");

    try {
      await axios.post("http://localhost:3001/responses", { 
        responses: securityFormEntries 
      });
      alert("Security questions saved successfully.");
      setSecurityFormEntries(createEmptyForm());
    } catch (error) {
      alert("Network Error: Could not save responses.");
    }
  };

  const getFilteredOptions = (currentIndex) => {
    const otherSelectedTexts = securityFormEntries
      .filter((_, idx) => idx !== currentIndex)
      .map(entry => entry.selectedQuestionText);

    return availableQuestions.filter(item => !otherSelectedTexts.includes(item.question));
  };

  return (
    <div className="app-container">
      <div className="visibility-control">
        <label>
          <input 
            type="checkbox" 
            checked={shouldMaskInput} 
            onChange={() => setShouldMaskInput(!shouldMaskInput)} 
          />
          Hide Sensitive Information
        </label>
      </div>

      <h1 className="main-header">Security Profile Setup</h1>

      <div className="form-content-area">
        {securityFormEntries.map((entry, index) => (
          <QuestionCard
            key={index}
            index={index}
            entryData={entry}
            optionsList={getFilteredOptions(index)}
            isMasked={shouldMaskInput} 
            onFieldUpdate={updateFormEntry}
          />
        ))}

        <button className="submission-button" onClick={validateAndSubmitForm}>
          Finalize Security Setup
        </button>
      </div>
    </div>
  );
}

export default App;
